def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (everything after '+')
        if '+' in v:
            v_without_build = v.split('+')[0]
        else:
            v_without_build = v

        # Split off pre-release (everything after '-')
        if '-' in v_without_build:
            version_part, prerelease_part = v_without_build.split('-', 1)
        else:
            version_part = v_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = version_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_identifiers = prerelease_part.split('.')
            # Convert identifiers to comparable form
            parsed_prerelease = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    parsed_prerelease.append((0, int(identifier)))
                else:
                    parsed_prerelease.append((1, identifier))
            prerelease_tuple = tuple(parsed_prerelease)
        else:
            prerelease_tuple = None

        return (major, minor, patch, prerelease_tuple)

    def sort_key(v):
        major, minor, patch, prerelease_tuple = parse_version(v)

        # For sorting: a version without prerelease sorts after one with prerelease
        # So we use (major, minor, patch, False if prerelease_tuple else True, prerelease_tuple or ())
        if prerelease_tuple is None:
            return (major, minor, patch, 1)
        else:
            return (major, minor, patch, 0, prerelease_tuple)

    # Use stable sort to preserve input order for equal precedence
    return sorted(versions, key=sort_key)

